test({ sr: 'fn se izvršava samo jednom', en: 'fn runs only once' }, () => {
  let calls = 0;
  const f = once(() => { calls++; return 42; });
  f(); f(); f();
  expect(calls).toBe(1);
});
test({ sr: 'kasniji pozivi vraćaju isti rezultat', en: 'later calls return the same result' }, () => {
  const f = once(() => ({ id: 1 }));
  const first = f();
  expect(first).toEqual({ id: 1 });
  expect(f()).toBe(first);
});
test({ sr: 'argumenti kasnijih poziva se ignorišu', en: 'arguments of later calls are ignored' }, () => {
  const f = once((x) => x * 2);
  expect(f(2)).toBe(4);
  expect(f(10)).toBe(4);
});

