test('an undefined result is remembered too', () => {
  let calls = 0;
  const f = once(() => { calls++; });
  expect(f()).toBe(undefined);
  f(); f();
  expect(calls).toBe(1);
});
test('falsy results are remembered too', () => {
  let calls = 0;
  const f = once(() => { calls++; return 0; });
  f(); f();
  expect(calls).toBe(1);
  expect(f()).toBe(0);
});
test('two once functions are independent', () => {
  let a = 0;
  let b = 0;
  const fa = once(() => { a++; return 'a'; });
  const fb = once(() => { b++; return 'b'; });
  expect(fa()).toBe('a');
  expect(fb()).toBe('b');
  expect(a).toBe(1);
  expect(b).toBe(1);
});
test('fn receives all arguments of the first call', () => {
  const f = once((a, b, c) => a + b + c);
  expect(f(1, 2, 3)).toBe(6);
});

